  // Get states list
  ConstRecVec StageList = ItinData->getValueAsListOfDefs("Stages");

  // For each stage
  unsigned N = NStages = StageList.size();
  for (unsigned I = 0; I < N;) {
    // Next stage
    const Record *Stage = StageList[I];

    // Form string as ,{ cycles, u1 | u2 | ... | un, timeinc, kind }
    int Cycles = Stage->getValueAsInt("Cycles");
    ItinString += "  { " + itostr(Cycles) + ", ";

    // Get unit list
    ConstRecVec UnitList = Stage->getValueAsListOfDefs("Units");

    // For each unit
    for (unsigned J = 0, M = UnitList.size(); J < M;) {
      // Add name and bitwise or
      ItinString += Name + "FU::" + UnitList[J]->getName().str();
      if (++J < M)
        ItinString += " | ";
    }

    int TimeInc = Stage->getValueAsInt("TimeInc");
    if (TimeInc < 0) {
      TimeInc = Cycles;
    }
    ItinString += ", " + itostr(TimeInc);

    int Kind = Stage->getValueAsInt("Kind");
    ItinString += ", (llvm::InstrStage::ReservationKinds)" + itostr(Kind);

    // Close off stage
    ItinString += " }";
    if (++I < N)
      ItinString += ", ";
  }
}

//
// FormItineraryOperandCycleString - Compose a string containing the
// operand cycle initialization for the specified itinerary.  N is the
// number of operands that has cycles specified.
//
void SubtargetEmitter::formItineraryOperandCycleString(
    const Record *ItinData, std::string &ItinString, unsigned &NOperandCycles) {
  // Get operand cycle list
  std::vector<int64_t> OperandCycleList =
      ItinData->getValueAsListOfInts("OperandCycles");

  // For each operand cycle
  NOperandCycles = OperandCycleList.size();
  ListSeparator LS;
  for (int OCycle : OperandCycleList) {
    // Next operand cycle
    ItinString += LS;
    ItinString += "  " + itostr(OCycle);
  }
}

void SubtargetEmitter::formItineraryBypassString(const std::string &Name,
                                                 const Record *ItinData,
                                                 std::string &ItinString,
                                                 unsigned NOperandCycles) {
  ConstRecVec BypassList = ItinData->getValueAsListOfDefs("Bypasses");
  unsigned N = BypassList.size();
  unsigned I = 0;
  ListSeparator LS;
  for (; I < N; ++I) {
    ItinString += LS;
    ItinString += Name + "Bypass::" + BypassList[I]->getName().str();
  }
  for (; I < NOperandCycles; ++I) {
    ItinString += LS;
    ItinString += " 0";
  }

  /// the maximum completion time for any stage in the itinerary.  If no stages
  /// exist, it defaults to one cycle.
  unsigned getStageLatency(unsigned ItinClassIndx) const {
    // If the target doesn't provide itinerary information, use a simple
    // non-zero default value for all instructions.
    if (isEmpty())
      return 1;

    // Calculate the maximum completion time for any stage.
    unsigned Latency = 0, StartCycle = 0;
    for (const InstrStage *IS = beginStage(ItinClassIndx),
           *E = endStage(ItinClassIndx); IS != E; ++IS) {
      Latency = std::max(Latency, StartCycle + IS->getCycles());
      StartCycle += IS->getNextCycles();
    }
    return Latency;
  }

  /// Return the cycle for the given class and operand. Return std::nullopt if
  /// the information is not available for the operand.
  virtual std::optional<unsigned> getOperandCycle(unsigned ItinClassIndx,
                                                  unsigned OperandIdx) const {
    if (isEmpty())
      return std::nullopt;

    unsigned FirstIdx = Itineraries[ItinClassIndx].FirstOperandCycle;
    unsigned LastIdx = Itineraries[ItinClassIndx].LastOperandCycle;
    if ((FirstIdx + OperandIdx) >= LastIdx)
      return std::nullopt;

    return OperandCycles[FirstIdx + OperandIdx];
  }

  /// Return true if there is a pipeline forwarding between instructions
  /// of itinerary classes DefClass and UseClasses so that value produced by an
  /// instruction of itinerary class DefClass, operand index DefIdx can be
  /// bypassed when it's read by an instruction of itinerary class UseClass,
  /// operand index UseIdx.
  bool hasPipelineForwarding(unsigned DefClass, unsigned DefIdx,
                             unsigned UseClass, unsigned UseIdx) const {
    unsigned FirstDefIdx = Itineraries[DefClass].FirstOperandCycle;
    unsigned LastDefIdx = Itineraries[DefClass].LastOperandCycle;
    if ((FirstDefIdx + DefIdx) >= LastDefIdx)
      return false;
    if (Forwardings[FirstDefIdx + DefIdx] == 0)
      return false;

    unsigned FirstUseIdx = Itineraries[UseClass].FirstOperandCycle;
    unsigned LastUseIdx = Itineraries[UseClass].LastOperandCycle;
    if ((FirstUseIdx + UseIdx) >= LastUseIdx)
      return false;

    return Forwardings[FirstDefIdx + DefIdx] ==
      Forwardings[FirstUseIdx + UseIdx];
  }

  /// Compute and return the use operand latency of a given itinerary
  /// class and operand index if the value is produced by an instruction of the
  /// specified itinerary class and def operand index. Return std::nullopt if
  /// the information is not available for the operand.
  std::optional<unsigned> getOperandLatency(unsigned DefClass, unsigned DefIdx,
                                            unsigned UseClass,
                                            unsigned UseIdx) const {
    if (isEmpty())
      return std::nullopt;

    std::optional<unsigned> DefCycle = getOperandCycle(DefClass, DefIdx);
    std::optional<unsigned> UseCycle = getOperandCycle(UseClass, UseIdx);
    if (!DefCycle || !UseCycle)
      return std::nullopt;

    if (UseCycle > *DefCycle + 1)
      return std::nullopt;

    UseCycle = *DefCycle - *UseCycle + 1;
    if (UseCycle > 0u &&
        hasPipelineForwarding(DefClass, DefIdx, UseClass, UseIdx))
      // FIXME: This assumes one cycle benefit for every pipeline forwarding.
      UseCycle = *UseCycle - 1;
    return UseCycle;
  }

  /// Return the number of micro-ops that the given class decodes to.
  /// Return -1 for classes that require dynamic lookup via TargetInstrInfo.
  int getNumMicroOps(unsigned ItinClassIndx) const {
    if (isEmpty())
      return 1;
    return Itineraries[ItinClassIndx].NumMicroOps;
  }
};

} // end namespace llvm

#endif // LLVM_MC_MCINSTRITINERARIES_H

// Reminder: this is used to compute the latency of RAW edges only.
std::optional<unsigned> AIEBaseInstrInfo::getOperandLatency(
    const InstrItineraryData *ItinData, const MachineInstr &DefMI,
    unsigned DefIdx, const MachineInstr &UseMI, unsigned UseIdx) const {
  std::optional<int> Lat = getSignedOperandLatency(ItinData, DefMI, DefIdx,
                                                   UseMI, UseIdx, SDep::Data);
  if (Lat) {
    // We have to maintain the semantics here and "cap" negative latencies at 0.
    int SignedLat = *Lat;
    return std::max(0, SignedLat);
  }

  // We are lacking scheduling info for the instructions, return an optimistic
  // value for the latency.
  assert(isPreRA(*DefMI.getMF()));
  return Lat;
}

std::optional<int> AIEBaseInstrInfo::getSignedOperandLatency(
    const InstrItineraryData *ItinData, const MachineInstr &SrcMI,
    unsigned SrcOpIdx, const MachineInstr &DstMI, unsigned DstOpIdx,
    SDep::Kind Kind) const {
  // We mostly copy the default implementation of getOperandLatency, but we
  // support WAR and WAW dependencies as well.
  // We also look a bit closer at zero-cost instructions to help pre-RA sched.

  // Use resolved schedule classes based on register classes to get correct
  // bypass information and operand latencies.
  const MachineRegisterInfo &MRI = SrcMI.getMF()->getRegInfo();
  const unsigned SrcClass = getSchedClass(
      SrcMI.getDesc(), make_range(SrcMI.operands_begin(), SrcMI.operands_end()),
      MRI);
  const unsigned DstClass = getSchedClass(
      DstMI.getDesc(), make_range(DstMI.operands_begin(), DstMI.operands_end()),
      MRI);
  std::optional<unsigned> SrcCycle =
      ItinData->getOperandCycle(SrcClass, SrcOpIdx);
  std::optional<unsigned> DstCycle =
      ItinData->getOperandCycle(DstClass, DstOpIdx);

  // This architecture has strict scheduling requirements. We require
  // itineraries for all "real" instructions.
  // For pre-RA scheduling, we cannot expect all instructions to have
  // itineraries as there still are generic opcodes.
  if (!isPreRA(*SrcMI.getMF())) {

    // In post-RA scheduling, "meta" instructions scheduled in a cycle are
    // always moved after the "real" instructions in that cycle. The latencies
    // below are meant to keep the natural ordering of the dependence.
    // Note this is purely cosmetic. If the instructions were to be re-ordered,
    // nothing would really happen because meta instructions are not emitted.
    // See schedule/meta_instrs.mir.
    if (SrcMI.isMetaInstruction() || isHardwareLoopStart(SrcMI.getOpcode()))
      return 1;
    if (DstMI.isMetaInstruction() || isHardwareLoopStart(DstMI.getOpcode()))
      return 0;

    if (SrcClass == 0 && !SrcMI.isMetaInstruction()) {
      LLVM_DEBUG(llvm::dbgs()
                 << "Warning!: no Scheduling class for " << SrcMI << "\n");
      report_fatal_error("Missing scheduling info.");
    }
    if (DstClass == 0 && !DstMI.isMetaInstruction()) {
      LLVM_DEBUG(llvm::dbgs()
                 << "Warning!: no Scheduling class for " << DstMI << "\n");
      report_fatal_error("Missing scheduling info.");
    }
    if (!SrcCycle && !SrcMI.isMetaInstruction()) {
      LLVM_DEBUG(llvm::dbgs()
                 << "Warning!: Scheduling class contains no information for "
                 << "Operand " << SrcOpIdx << " of Src " << SrcMI);
      report_fatal_error("Missing scheduling info.");
    }
    if (!DstCycle && !DstMI.isMetaInstruction()) {
      LLVM_DEBUG(llvm::dbgs()
                 << "Warning!: Scheduling class contains no information for "
                 << "Operand " << DstOpIdx << " of Dst " << DstMI);
      report_fatal_error("Missing scheduling info.");
    }
  }

  // Zero cost instructions like INSERT_SUBREG used as def or use will return
  // an unknown latency in the standard itinerary logic, which would be max-ed
  // to 0. By setting the use cycle to the earliest possible, we make sure that
  // the result operand latency of late writers is respected. As an example.
  // VLDA -> INSERT_SUBREG -> VMAX_LT wouldn't resepect the load latency in
  // pre-regalloc scheduling, since both edges get zero latency.
  //
  // Note that this takes the hit of a transitive latency on this intermediate
  // zero-cost node conservatively; a late reading user of DstMI will be pushed
  // later than necessary.
  if (Kind == SDep::Data && !DstCycle && isZeroCost(DstMI.getOpcode())) {
    DstCycle = 1;
  }

  if (!SrcCycle || !DstCycle) {
    LLVM_DEBUG(llvm::dbgs() << "Warning!: Missing scheduling info:\n"
                            << "  From Op #" << SrcOpIdx << " of " << SrcMI
                            << "  To   Op #" << DstOpIdx << " of " << DstMI);
    return std::nullopt;
  }

  int SrcCycleVal = *SrcCycle;
  int DstCycleVal = *DstCycle;
  if (Kind == SDep::Data) {
    // Typical bypass case: data from a producer is available earlier for a
    // consumer.
    SrcCycleVal -=
        getNumBypassedCycles(ItinData, SrcClass, SrcOpIdx, DstClass, DstOpIdx);
  }
  if (Kind == SDep::Anti) {
    // "Reverse" case: we need to penalize WAR dependencies, because if the
    // bypass is taken by the write, then the read could get the newly-written
    // value, not respecting the WAR edge. See negative_latencies/bypass.mir
    DstCycleVal -=
        getNumBypassedCycles(ItinData, DstClass, DstOpIdx, SrcClass, SrcOpIdx);
  }

  int Diff = SrcCycleVal - DstCycleVal;
  int Latency = Kind == SDep::Anti ? (Diff) : (Diff + 1);
  return Latency;
}

unsigned AIEBaseInstrInfo::getNumBypassedCycles(
    const InstrItineraryData *ItinData, unsigned DefSchedClass, unsigned DefIdx,
    unsigned UseSchedClass, unsigned UseIdx) const {

  // FIXME: This assumes one cycle benefit for every pipeline forwarding.
  return ItinData->hasPipelineForwarding(DefSchedClass, DefIdx, UseSchedClass,
                                         UseIdx)
             ? 1
             : 0;
}

/// FIXME: Delays for locks to reach the core aren't completely described in
/// the ISA. The numbers are therefore conservative.
int AIEBaseInstrInfo::getCoreStallCycleAfterLock() const { return 2; }
int AIEBaseInstrInfo::getCoreResumeCycleAfterLock() const { return 8; }
int AIEBaseInstrInfo::getCoreResumeCycleAfterAcquireStore() const {
  return getCoreResumeCycleAfterLock();
}
int AIEBaseInstrInfo::getCoreResumeCycleAfterAcquireLoad() const {
  return getCoreResumeCycleAfterLock();
}
int AIEBaseInstrInfo::getCoreResumeCycleAfterReleaseStore() const {
  return getCoreResumeCycleAfterLock();
}
int AIEBaseInstrInfo::getCoreResumeCycleAfterReleaseLoad() const {
  return getCoreResumeCycleAfterLock();
}

std::optional<int>
AIEBaseInstrInfo::getLockResumeDelay(const MachineInstr &Lock,
                                     const MachineInstr &MemMI) const {
  const bool IsLoad = MemMI.mayLoad();
  const bool IsStore = MemMI.mayStore();
  // The resume window only constrains memory operations.
  if (!IsLoad && !IsStore)
    return std::nullopt;

  const unsigned SchedClass = getSchedClass(MemMI.getDesc(), MemMI.operands(),
                                            MemMI.getMF()->getRegInfo());

  // TM ops hold no lckLdaRsrc/lckStRsrc tokens, so the resume-cycle formula
  // does not apply; only same-bundle issue must be prevented.
  if (isTMAccessSchedClass(SchedClass))
    return 1;

  // some Instructions have mayLoadOrStore but don't access memory, e.g., stream
  // ss moves
  std::optional<int> OptFirstMemCycle =
      getFirstMemoryCycleForLockOrdering(SchedClass);
  if (!OptFirstMemCycle)
    return std::nullopt;

  // Handle partword stores, that load and store
  const bool IsLoadOnly = IsLoad && !IsStore;
  const int AcquireResumeCycle = IsLoad ? getCoreResumeCycleAfterAcquireLoad()
                                        : getCoreResumeCycleAfterAcquireStore();
  const int ReleaseResumeCycle = IsLoadOnly
                                     ? getCoreResumeCycleAfterReleaseLoad()
                                     : getCoreResumeCycleAfterReleaseStore();
  const int CoreResumeCycle = isAcquire(Lock.getOpcode()) ? AcquireResumeCycle
                              : isRelease(Lock.getOpcode())
                                  ? ReleaseResumeCycle
                                  : getCoreResumeCycleAfterLock();

  const bool IsStoreOnly = IsStore && !IsLoad;
  const int FirstIssueMemCycle =
      isRelease(Lock.getOpcode()) && IsStoreOnly
          ? std::min(*OptFirstMemCycle, ReleaseResumeCycle)
          : *OptFirstMemCycle;
  return CoreResumeCycle - FirstIssueMemCycle + 1;
}

std::optional<int>
AIEBaseInstrInfo::getLockStallDelay(const MachineInstr &MemMI) const {
  // The stall window only constrains memory operations.
  if (!MemMI.mayLoadOrStore())
    return std::nullopt;

  // Ensure the memory operation retires before the core stalls. For load-only
  // instructions, use the lock-ordering cycle (write-back stage) rather than
  // the bare memory-access cycle, since the load data must be fully committed
  // before the lock can observe it. nullopt means no backward lock-ordering
  // constraint for this class (e.g. vmovx ss has mayLoadOrStore but does not
  // access memory).
  const bool IsLoadOnly = MemMI.mayLoad() && !MemMI.mayStore();
  std::optional<int> OptLastMemCycle = getLastMemoryCycleForLockOrdering(
      getSchedClass(MemMI.getDesc(),
                    make_range(MemMI.operands_begin(), MemMI.operands_end()),
                    MemMI.getMF()->getRegInfo()),
      IsLoadOnly);
  if (!OptLastMemCycle)
    return std::nullopt;

  return *OptLastMemCycle - getCoreStallCycleAfterLock() + 1;
}

bool FuncUnitWrapper::conflict(const FuncUnitWrapper &Other) const {
  // Load-Load and Store-Store conflicts are checked independently.
  // Loads and stores don't conflict with each other on AIE (separate HW ports).
  if ((Slots & Other.Slots) != 0 || (MemoryBanks & Other.MemoryBanks) != 0 ||
      (LoadMemObjectsBits & Other.LoadMemObjectsBits) != 0 ||
      (StoreMemObjectsBits & Other.StoreMemObjectsBits) != 0 ||
      (Conflicts & Other.Slots) != 0 || (Slots & Other.Conflicts) != 0 ||
      Required.overlap(Other.Required) || Reserved.overlap(Other.Required) ||
      Required.overlap(Other.Reserved)) {

    return true;
  }

  // Note: Don't check formats unless both have occupied slots.
  // This allows representing a blocked cycle (Slots = ~0) without knowing
  // the slot and format details.
  return Slots && Other.Slots &&
         !FormatInterface->isFormatAvailable(Slots | Other.Slots);
}

namespace {

using FuncUnitWrapperAction =
    std::function<bool(int C, const FuncUnitWrapper &)>;

// Central itinerary data interpreter
// It will call Action with the cycle number and the FuncUnits,
// returning true as soon as Action returns true.
// A full traversal can be made by returning false.
bool anyStage(ArrayRef<const InstrStage> Stages, FuncUnitWrapperAction Action,
              std::optional<int> FUDepthLimit = std::nullopt) {
  int Cycle = 0;
  for (const InstrStage &IS : Stages) {
    if (FUDepthLimit && Cycle >= *FUDepthLimit) {
      break;
    }
    const FuncUnitWrapper ThisCycle(IS);
    for (unsigned C = 0; C < IS.getCycles(); C++) {
      if (Action(Cycle + C, ThisCycle)) {
        return true;
      }
    }
    Cycle += IS.getNextCycles();
  }
  return false;
}

bool AIEHazardRecognizer::checkConflict(
    const ResourceScoreboard<FuncUnitWrapper> &Scoreboard,
    const InstrItineraryData *ItinData, unsigned SchedClass, SlotBits SlotSet,
    SlotBits ConflictSet, MemoryBankBits MemoryBanks,
    MemoryObjectPair MemObjectsBits, SmallVector<int, 2> MemoryAccessCycles,
    int DeltaCycles, std::optional<int> FUDepthLimit) {

  // Verify format hazards
  FuncUnitWrapper EmissionCycle(SlotSet, ConflictSet);
  if (EmissionCycle.conflict(Scoreboard[DeltaCycles]))
    return true;

  // Verify memory bank and shared object hazards
  if (!MemoryAccessCycles.empty()) {
    const SlotBits Slots = 0;
    const SlotBits Conflicts = 0;
    FuncUnitWrapper MemoryAccessCycle(Slots, Conflicts, MemoryBanks,
                                      MemObjectsBits.Load,
                                      MemObjectsBits.Store);

    for (auto Cycles : MemoryAccessCycles) {
      // MemoryAccessCycles starts counting from 1, so we need to subtract 1
      int AccessCycle = DeltaCycles + Cycles - 1;
      assert(Scoreboard.isInRange(AccessCycle));
      if (MemoryAccessCycle.conflict(Scoreboard[AccessCycle])) {
        LLVM_DEBUG(dbgs() << "*** Memory bank/Object conflict in cycle="
                          << AccessCycle << ":\n";
                   MemoryAccessCycle.dump(); dbgs() << "\n");
        return true;
      }
    }
  }

  // Note that DeltaCycles will be negative for bottom-up scheduling.

  /// Check ThisCycle for a conflict at Cycle relative to the start of the
  /// itinerary.
  FuncUnitWrapperAction CycleConflict =
      [&Scoreboard, DeltaCycles](int Cycle, const FuncUnitWrapper &ThisCycle) {
        const int StageCycle = DeltaCycles + Cycle;
        assert(Scoreboard.isInRange(StageCycle));
        if (ThisCycle.conflict(Scoreboard[StageCycle])) {
          LLVM_DEBUG(dbgs() << "*** Hazard in cycle=" << StageCycle
                            << " EC=" << StageCycle - DeltaCycles << ":\n";
                     ThisCycle.dump(); dbgs() << "\n");
          return true;
        }
        return false;
      };

  return anyStage(ItinData->getStages(SchedClass), CycleConflict, FUDepthLimit);
}

int AIEHazardRecognizer::computeInstrSelfMII(const MachineInstr &MI) const {
  const MCInstrDesc &Desc = MI.getDesc();
  const unsigned SchedClass =
      TII->getSchedClass(Desc, MI.operands(), MI.getMF()->getRegInfo());
  // Instructions without scheduling info cannot self-conflict.
  if (SchedClass == 0 || PipelineDepth <= 0)
    return 1;

  // Scan all candidate II values. Self-conflict is not monotone: a
  // non-conflicting II can be followed by a conflicting one (e.g. resource
  // uses at cycles {0, 3, 7} conflict at II=7 because 7 mod 7 == 0 mod 7,
  // even if II=5 is conflict-free). We therefore track the largest II that
  // self-conflicts and return that value plus one.
  int SelfMII = 1;
  for (int II = 1; II <= PipelineDepth; ++II) {
    std::vector<FuncUnitWrapper> SelfBoard(II);
    if (anyStage(ItinData->getStages(SchedClass),
                 [&](int Cycle, const FuncUnitWrapper &ThisCycle) {
                   const int Mod = Cycle % II;
                   if (ThisCycle.conflict(SelfBoard[Mod]))
                     return true;
                   SelfBoard[Mod] |= ThisCycle;
                   return false;
                 }))
      SelfMII = II + 1;
  }
  return SelfMII;
}

unsigned AIEHazardRecognizer::getPipelineDepth() const { return PipelineDepth; }

unsigned AIEHazardRecognizer::getMaxLatency() const { return MaxLatency; }

int AIEHazardRecognizer::getConflictHorizon() const {
  return int(std::max(PipelineDepth, MaxLatency));
}

void AIEHazardRecognizer::computeMaxLatency() {
  assert(ItinData && !ItinData->isEmpty());
  unsigned FirstRW = std::numeric_limits<unsigned>().max();
  unsigned LastRW = 0;
  FuncUnitWrapperAction MaxDepth = [this](int C, const FuncUnitWrapper &) {
    PipelineDepth = std::max(PipelineDepth, C);
    return false;
  };
  for (unsigned SchedClass = 0; !ItinData->isEndMarker(SchedClass);
       ++SchedClass) {
    anyStage(ItinData->getStages(SchedClass), MaxDepth);
    for (unsigned OpIdx = 0;; OpIdx++) {
      std::optional<unsigned> OpLat =
          ItinData->getOperandCycle(SchedClass, OpIdx);
      if (!OpLat) {
        break;
      }
      FirstRW = std::min(FirstRW, *OpLat);
      LastRW = std::max(LastRW, *OpLat);
    }
  }

  // This is worst case, ignoring bypasses and same-cycle WAR
  MaxLatency = LastRW - FirstRW + 1;
  FirstRW = TII->getMinFirstMemoryCycle();
  LastRW = TII->getMaxLastMemoryCycle();
  MaxLatency = std::max(MaxLatency, int(LastRW - FirstRW + 1));
  PipelineDepth = std::max(PipelineDepth, int(LastRW));

int PostPipeliner::getResMII(MachineBasicBlock &LoopBlock) {
  // Add up per-slot instruction counts using primary slot sets.
  // Conflict sets are not used here because multi-slot instructions
  // (e.g. XM) accumulate conflicts from all constituent slots (X + M),
  // causing them to dominate the maximum and over-estimate ResMII.
  SlotCounts Counts;
  for (auto &MI : LoopBlock) {
    Counts += getSlotCounts(MI.getOpcode(), TII);
  }
  int MII = Counts.max();

  // A single instruction whose pipeline stages alias at a given II causes a
  // resource conflict with itself in the next iteration.
  for (auto &MI : LoopBlock) {
    MII = std::max(MII, HR.computeInstrSelfMII(MI));
  }

  LLVM_DEBUG(dbgs() << "PostPipeliner: ResMII=" << MII << "\n");
  return MII;
}

// We compute the Minimum Initiation Interval given by recurrences (or
// circuits) in the dependence graph.
// A recurrence is identified by a backedge for which there is a path
// between Dst and Src. Backedges are defined by edges between the
// first and the second iteration.
// The length of each circuit is computed by a depth-first traversal
// starting from Dst, trying to find Src. Revisiting paths is prevented by
// caching the height to Src.

void PostPipeliner::computeRecMII() {
  RecMII = 0;
  for (int K = 0; K < NInstr; K++) {
    SUnit &Src = DAG->SUnits[K];
    for (auto &Dep : Src.Succs) {
      SUnit *Dst = Dep.getSUnit();
      if (Dst->NodeNum >= unsigned(NInstr)) {
        NodeInfo Me = Info[K];
        int SNum = Dst->NodeNum - NInstr;
        if (Me.Ancestors.count(SNum)) {
          // The successor is represented by one of
          // my ancestors. That means we have a circuit,
          // which may be the longest one. We find the longest path between
          // that ancestor and this node, adding the latency of the
          // backedge.
          HCache Heights(NInstr);
          auto Height = computeHeight(Heights, &DAG->SUnits[SNum], &Src);
          assert(Height);

          int Circuit = *Height + Dep.getSignedLatency();
          RecMII = std::max(Circuit, RecMII);
          LLVM_DEBUG(dbgs() << "Backedge " << K << " -> " << SNum
                            << " circuit=" << Circuit << "\n");
        }
      }
    }
  }
  LLVM_DEBUG(dbgs() << "RecMII=" << RecMII << "\n");
}

